------------ import ------------
local KTool = CS.Engine.Lib.KTool
------------ import ------------

------------ define ------------
local BehaviourActionType = typeof(CS.Engine.Lib.BehaviourAction)
------------ define ------------

---@class HomeTimeNode
local HomeTimeNode = Class('HomeTimeNode')

function HomeTimeNode:__init()
    ---@type UnityEngine.RectTransform
    self.textUID = nil
    ---@type UnityEngine.RectTransform
    self.textTime = nil
    self.isServerTime = true
    self.startTime = os.time()
    ---@type PlayerDojo
    self.playerDojo = nil
    self.loopStartTime = os.time()
    self.isProcessing = false
end

function HomeTimeNode:__delete()
    ---@type UnityEngine.RectTransform
    self.textUID = nil
    ---@type UnityEngine.RectTransform
    self.textTime = nil
    self.isServerTime = true
    ---@type PlayerDojo
    self.playerDojo = nil
    self.loopStartTime = nil
end

function HomeTimeNode:Awake()
    if not GameUtils.isZmFunction() then
        CfUtils.SetActive(self.controller, false)
    else
        self.startTime = os.time()
        self.textUID = self.controller.transform:Find("TxtUID")
        self.textTime = self.controller.transform:Find("TxtTime")
        ---@type PlayerComponent
        local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        self.playerDojo = playerComponent.playerDojo
        local uidInfoStr = string.format('UID:%d', self.playerDojo.playerId)
        CfUtils.FillText(self.textUID, uidInfoStr)
        self:UpdateTextInfo()
        SetButtonAction(self.controller.gameObject, function()
            ---点击事件
            self.isProcessing = true
            self.isServerTime = not self.isServerTime
            self.loopStartTime = os.time()
            self:UpdateTextInfo()
            self.isProcessing = false
        end)
    end
end

function HomeTimeNode:UpdateTextInfo()
    if self.textTime and self.playerDojo then
        ---@type PlayerDojo
        local playerDojo = self.playerDojo
        if self.isServerTime then
            local uidInfoStr = GameUtils.CheckUTCTimeformat(string.format("Server time: %s", GameUtils.l10nTimeData('%m/%d %H:%M', playerDojo:GetServerTime())))
            CfUtils.FillText(self.textTime, uidInfoStr)
        else
            local uidInfoStr = string.format("Local time:  %s", GameUtils.l10nTimeData('%m/%d %H:%M', GameUtils.ToClientTimestamp(playerDojo:GetServerTime())))
            CfUtils.FillText(self.textTime, uidInfoStr)
        end
    end
end

function HomeTimeNode:OnEnable()
    if GameUtils.isZmFunction() then
        self.isProcessing = false
        ---@type Engine.Lib.BehaviourAction
        local behaviorAction            = KTool.GetOrAddComponent(self.controller.gameObject, BehaviourActionType)
        behaviorAction.UpdateAction     = function()
            ---更新时间的逻辑
            if os.time() - self.startTime >= 60 then
                self.startTime = os.time()
                self:UpdateTextInfo()
            elseif os.time() - self.loopStartTime >= 10 and not self.isProcessing then
                self.loopStartTime = os.time()
                self.isServerTime = not self.isServerTime
                self:UpdateTextInfo()
            end
        end
        self._behaviorAction            = behaviorAction
    end
end

function HomeTimeNode:OnDestroy()
    if not isNull(self._behaviorAction) then
        self._behaviorAction.UpdateAction     = nil
    end
    self.isProcessing = false
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return HomeTimeNode